        {
          "activityTemplate": null,
          "kind": "explanation",
          "visual": null,
          "visualKind": "none",
          "brief": "Inside the box, V = 0, so the time-independent Schrödinger equation becomes −ℏ²ψ″/(2m) = Eψ. The walls, not a varying interior potential, constrain the solutions.",
          "skills": [
            0
          ]
        },
        {
          "activityTemplate": null,
          "kind": "explanation",
          "visual": null,
          "visualKind": "none",
